/** Builds a complete site architecture from a Design Intelligence profile. */
class Design_Core_Elementor_Page_Strategy_Engine {
 const SCHEMA_VERSION=1;
 public function plan(array $brief,array $profile){$id=sanitize_key((string)($profile['product']['id']??$profile['id']??''));$cat=strtolower((string)($profile['product']['category']??$profile['category']??''));$goal=sanitize_key((string)($brief['primary_goal']??'inform_and_convert'));$family=$this->family($id,$cat);$pages=$this->pages($family,$id);$requested=array_values(array_filter(array_map('sanitize_key',(array)($brief['requested_pages']??array()))));if($requested)$pages=$this->prioritize($pages,$requested);$ps=(array)($profile['page_strategy']??array());return array('schema_version'=>1,'type'=>'site-strategy','industry_profile'=>$id,'family'=>$family,'primary_goal'=>$goal,'primary_cta'=>$this->primary_cta($goal,$family),'secondary_cta'=>$this->secondary_cta($family),'global_components'=>$this->globals($family),'pages'=>$pages,'homepage'=>array('shell'=>sanitize_key((string)($ps['recommended_shell']??($pages[0]['shell']??'marketing-home'))),'sections'=>array_values(array_map('sanitize_key',(array)($ps['sections']??array())))),'responsive_contract'=>array('viewports'=>array(1440,1280,1024,768,390),'mobile_navigation'=>'collapsed','mobile_primary_cta'=>'visible-without-horizontal-overflow','touch_target_min_px'=>44,'reflow_required'=>true),'visual_contract'=>array('reference_required'=>('none'!==($brief['reference_mode']??'none')),'target_similarity'=>0.95,'max_correction_iterations'=>4,'compare_geometry'=>true,'compare_computed_styles'=>true,'structural_diff'=>true),'rules'=>array('one-obvious-primary-action-per-page','reuse-global-design-tokens','prefer-native-elementor-controls','render-before-visual-pass','never-mark-unverified-visual-as-pass'));}
 private function family($id,$cat){$g=array('medical'=>array('veterinary','medical-clinic','dental-clinic','hospital','physiotherapy','mental-health'),'commerce'=>array('marketplace','directory','car-dealer','ecommerce','ecommerce-luxury'),'property'=>array('real-estate','property-developer'),'hospitality'=>array('restaurant','cafe','hotel','resort','travel'),'education'=>array('school','university','online-course','training-provider'),'content'=>array('news','blog'),'creative'=>array('agency','portfolio','photography','architecture','interior-design'),'community'=>array('membership','nonprofit','event'),'technology'=>array('software-product','developer-tool','cybersecurity','saas-general','micro-saas'));foreach($g as $f=>$ids)if(in_array($id,$ids,true))return $f;if(false!==strpos($cat,'medical')||false!==strpos($cat,'clinic'))return 'medical';return 'service';}
 private function pages($f,$id){if('medical'===$f)return array($this->p('home','Home','veterinary'===$id?'veterinary-home':'medical-home',1),$this->p('services','Services','service-index',1),$this->p('service-detail','Service Detail','service-detail',1),$this->p('team','veterinary'===$id?'Veterinarians':'Specialists','team-directory',1),$this->p('profile','Professional Profile','profile-detail',1),$this->p('booking','Book Appointment','appointment-booking',1),$this->p('emergency','Emergency','emergency','veterinary'===$id||'hospital'===$id),$this->p('care-plans','Care Plans','care-plans','veterinary'===$id),$this->p('pricing','Pricing','pricing',0),$this->p('facilities','Facilities','facilities',0),$this->p('blog','Health Resources','blog-home',0),$this->p('article','Resource Article','article',0),$this->p('about','About','about',0),$this->p('contact','Contact','contact',1),$this->p('account','Client Portal','portal-dashboard','veterinary'===$id));if('commerce'===$f)return array($this->p('home','Home','ecommerce-home',1),$this->p('catalog','Catalog','shop',1),$this->p('category','Category','category',1),$this->p('detail','Detail','product-detail',1),$this->p('about','About','about',0),$this->p('blog','Resources','blog-home',0),$this->p('contact','Contact','contact',1));if('property'===$f)return array($this->p('home','Home','real-estate-home',1),$this->p('properties','Properties','property-list',1),$this->p('property','Property Detail','property-detail',1),$this->p('team','Agents','team-directory',0),$this->p('profile','Agent Profile','profile-detail',0),$this->p('about','About','about',0),$this->p('contact','Contact','contact',1));if('hospitality'===$f){$hotel=in_array($id,array('hotel','resort'),true);return array($this->p('home','Home',$hotel?'hotel-home':'restaurant-home',1),$this->p('offerings',$hotel?'Rooms':'Menu',$hotel?'rooms':'menu',1),$this->p('detail',$hotel?'Room Detail':'Experience','room-detail',0),$this->p('reservation','Reservations','reservation',1),$this->p('gallery','Gallery','facilities',0),$this->p('about','About','about',0),$this->p('contact','Contact','contact',1));}if('education'===$f)return array($this->p('home','Home','education-home',1),$this->p('programs','Programs / Courses','course-list',1),$this->p('program-detail','Program Detail','course-detail',1),$this->p('team','Faculty / Instructors','team-directory',0),$this->p('about','About','about',0),$this->p('blog','Resources','blog-home',0),$this->p('contact','Contact','contact',1));if('content'===$f)return array($this->p('home','Home','blog-home',1),$this->p('archive','Archive','archive',1),$this->p('article','Article','article',1),$this->p('about','About','about',0),$this->p('contact','Contact','contact',0));if('creative'===$f)return array($this->p('home','Home','portfolio-home',1),$this->p('work','Work','project-list',1),$this->p('project','Project Detail','project-detail',1),$this->p('services','Services','service-index',0),$this->p('about','About','about',1),$this->p('contact','Contact','contact',1));if('technology'===$f)return array($this->p('home','Home','saas-home',1),$this->p('features','Features','feature-detail',1),$this->p('pricing','Pricing','pricing',1),$this->p('resources','Resources','blog-home',0),$this->p('article','Article','article',0),$this->p('contact','Contact / Sales','contact',1));if('community'===$f)return array($this->p('home','Home','marketing-home',1),$this->p('programs','Programs','service-index',1),$this->p('events','Events','event',0),$this->p('about','About','about',1),$this->p('blog','Stories','blog-home',0),$this->p('contact','Contact','contact',1));return array($this->p('home','Home','service-home',1),$this->p('services','Services','service-index',1),$this->p('service-detail','Service Detail','service-detail',1),$this->p('team','Team','team-directory',0),$this->p('case-studies','Case Studies','project-list',0),$this->p('about','About','about',1),$this->p('blog','Resources','blog-home',0),$this->p('contact','Contact','contact',1));}
 private function p($id,$label,$shell,$required){return array('id'=>$id,'label'=>$label,'shell'=>$shell,'required'=>(bool)$required,'status'=>'planned');}private function prioritize($pages,$req){$home=array();$rest=array();foreach($pages as $pg){if('home'===$pg['id']){$home[]=$pg;}else{$rest[]=$pg;}}usort($rest,static function($a,$b)use($req){$ai=array_search($a['id'],$req,true);$bi=array_search($b['id'],$req,true);return(false===$ai?999:$ai)<=>(false===$bi?999:$bi);});return array_merge($home,$rest);}private function primary_cta($g,$f){$m=array('appointment_booking'=>'Book Appointment','lead_generation'=>'Request a Consultation','commerce'=>'Browse Products','reservation'=>'Reserve Now','membership'=>'Join Now','donation'=>'Donate','content_consumption'=>'Read Latest','portfolio'=>'View Work');return $m[$g]??('medical'===$f?'Book Appointment':'Get Started');}private function secondary_cta($f){$m=array('medical'=>'Explore Services','commerce'=>'Browse Categories','property'=>'View Properties','hospitality'=>'Explore','education'=>'View Programs','creative'=>'View Work','technology'=>'See How It Works','content'=>'Browse Topics');return $m[$f]??'Learn More';}private function globals($f){$b=array('header','mobile-navigation','footer','breadcrumb','button-system','form-system','notification-states');if('medical'===$f)$b[]='emergency-shortcut';if(in_array($f,array('commerce','property','hospitality'),true))$b[]='search-or-booking-entry';return $b;}
}
